from pathlib import Path
import subprocess

ROOT = Path.cwd()
EXPECTED = "ac6e8ab4a5355ca47336c038472d25593a07177d"

def git(*args):
    return subprocess.check_output(["git", *args], cwd=ROOT, text=True).strip()

head = git("rev-parse", "HEAD")
if head != EXPECTED:
    raise SystemExit(
        f"This patch was built for commit {EXPECTED[:7]} but HEAD is {head[:7]}. "
        "Checkout/pull ac6e8ab first, then run the patch again."
    )

def replace_once(path: Path, old: str, new: str, label: str):
    text = path.read_text(encoding="utf-8")
    if new in text:
        print(f"{label}: already applied")
        return
    if old not in text:
        raise SystemExit(f"{label}: expected block not found in {path}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")
    print(f"{label}: patched")

